import sys, html, re
sys.path.insert(0, '.')
from data import ENTRIES, HELD_SECTIONS, DEST

DT = dict(DEST)
ORDER = [k for k, _ in DEST]
FILE = {'POSITIONS': 'POSITIONS.md', 'FACTS': 'FACTS.md'}
KIND_NOTE = {'whole': 'whole', 'split': 'a part; the rest stays', 'stays': 'stays; borderline'}

def md_title(t):
    return t

# ---------- gather by destination ----------
by = {k: {'e': [], 'h': []} for k in ORDER}
for e in ENTRIES:
    for (d, what, already) in e['homes']:
        by[d]['e'].append((e, what, already))
for sec, pts in HELD_SECTIONS:
    for (line, opening, status, homes) in pts:
        for (d, what) in homes:
            by[d]['h'].append((sec, line, opening, status, what))

# ---------- the note ----------
def note_moves():
    out = []
    for d in ORDER:
        E, Hs = by[d]['e'], by[d]['h']
        if not E and not Hs:
            continue
        out.append(f"### {DT[d]}\n")
        for (e, what, already) in sorted(E, key=lambda x: (x[0]['src'] != 'POSITIONS', x[0]['line'])):
            k = e['kind']
            tag = 'whole' if k == 'whole' else ('a part; the rest stays' if k == 'split' else 'stays in the record; borderline')
            al = ' Already there.' if already else ''
            bl = ' Borderline (section 2.3).' if e.get('border') and k != 'stays' and e['homes'][0][0] == d else ''
            if k == 'stays':
                al = ' Already there; the entry stays (section 2.3).'
            out.append(f"- `{FILE[e['src']]}:{e['line']}`, \"{e['title']}\" ({tag}): {what}.{al}{bl}")
        for (sec, line, opening, status, what) in sorted(Hs, key=lambda x: x[1]):
            out.append(f"- `HELD.md:{line}`, {opening} ({status}): {what}.")
        out.append("")
    return "\n".join(out)

def note_index():
    out = []
    for f in ('POSITIONS', 'FACTS'):
        items = []
        for e in sorted([x for x in ENTRIES if x['src'] == f], key=lambda x: x['line']):
            homes = ", ".join(dict.fromkeys(h[0] for h in e['homes']))
            items.append(f"{e['line']} {e['kind']} → {homes}")
        out.append(f"- `{FILE[f]}`: " + "; ".join(items) + ".")
    items = []
    for sec, pts in HELD_SECTIONS:
        for (line, opening, status, homes) in pts:
            items.append(f"{line} {status} → " + ", ".join(dict.fromkeys(h[0] for h in homes)))
    out.append("- `HELD.md`: " + "; ".join(items) + ".")
    return "\n".join(out)

# ---------- the page ----------
def esc(s):
    s = html.escape(s, quote=False)
    s = re.sub(r'`([^`]+)`', r'<code>\1</code>', s)
    return s

PAGE_GROUP = {  # page sections: key, heading, list of dest keys, intro
}

def held_label(sec, line, opening):
    m = re.match(r'(\d\d:\d\dx?|\d\d:\dx|\(\d\d:\d\d UTC\))\s*(.*)', opening)
    date = re.search(r'\((\d{4}-\d\d-\d\d)\)', sec)
    day = {'2026-10-13': '13 Oct', '2026-10-12': '12 Oct', '2026-09-27': '27 Sep'}.get(date.group(1) if date else '', '')
    if opening.startswith('('):
        t = opening[1:6]
        return f"Your point of {t}, 9 Oct, on fortress-repo", line
    if m and m.group(1)[0].isdigit():
        t = m.group(1)
        if t == '00:4x':
            t = 'about 00:45'
        if sec.startswith('Held in chat (2026-10-12)') and t.startswith('00'):
            day = '13 Oct'
        return f"Your point of {t}, {day}", line
    return f"Your point of {day}", line

def page_points(d):
    """Return list of (speak_html, source_text)."""
    pts = []
    E, Hs = by[d]['e'], by[d]['h']
    for (e, what, already) in sorted(E, key=lambda x: (x[0]['src'] != 'POSITIONS', x[0]['line'])):
        k = e['kind']
        frm = 'from POSITIONS' if e['src'] == 'POSITIONS' else 'from FACTS'
        if k == 'split':
            frm = 'a part of it, ' + frm
        t = e['title'].replace(' ...', '…')
        sp = f"<b>“{esc(t)}”</b>, {frm}: {esc(what)}."
        if k == 'stays':
            sp += " The entry itself stays in the record."
        elif already:
            sp += " It's already there."
        if e.get('border') and e['homes'][0][0] == d:
            sp += f" Borderline: {esc(e['border'])}."
        src = f"{FILE[e['src']]}:{e['line']}"
        pts.append((sp, src))
    # held: individual for rule/question/owed; grouped for settled/done
    grouped = [h for h in Hs if h[3] in ('settled', 'done')]
    for h in sorted([h for h in Hs if h[3] not in ('settled', 'done')], key=lambda x: x[1]):
        sec, line, opening, status, what = h
        lab, _ = held_label(sec, line, opening)
        kind = {'rule': 'a rule to write', 'question': 'your open question', 'owed': 'an answer owed to you'}[status]
        pts.append((f"{lab}, {kind}: {esc(what)}.", f"HELD.md:{line}"))
    if grouped:
        grouped.sort(key=lambda x: x[1])
        items = "; ".join(esc(g[4]) for g in grouped)
        n = len(grouped)
        word = 'One point' if n == 1 else f"{n} of your held points"
        verb = 'is' if n == 1 else 'are'
        pts.append((f"{word} {verb} settled or done, so {'it closes' if n == 1 else 'they close'} with nothing new to write: {items}.",
                    "HELD.md:" + ", ".join(str(g[1]) for g in grouped)))
    return pts

def page_section(sid, heading, intro_points, dests, extra_after=None):
    pts = list(intro_points)
    for d in dests:
        pts += page_points(d)
    o = [f'  <section aria-labelledby="h-{sid}">',
         '    <div class="head">',
         f'      <h2 id="h-{sid}">{heading}</h2>',
         f'      <button class="select" type="button" data-target="s-{sid}" aria-label="Select the text of this section">Select</button>',
         '    </div>',
         f'    <div class="speak" id="s-{sid}">']
    for sp, _ in pts:
        o.append(f'      <p class="pt">{sp}</p>')
    o.append('    </div>')
    o.append('    <div class="refs">')
    o.append('      <h3>Sources</h3>')
    for i, (_, src) in enumerate(pts, 1):
        if src:
            o.append(f'      <p><b>{i}.</b> <code>{esc(src)}</code></p>' if '`' not in src and ' ' not in src else f'      <p><b>{i}.</b> {esc(src)}</p>')
    o.append('    </div>')
    o.append('  </section>')
    return "\n".join(o)

if __name__ == '__main__':
    open('note_moves.md', 'w').write(note_moves())
    open('note_index.md', 'w').write(note_index())
    print('ok')

